describe('Table Filter by Search Input', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="table-container"]').should('be.visible');
  });

  it('should filter table rows when typing in search input', () => {
    // Get initial row count
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);
    const initialRowCount = cy.get('[data-testid="table-row"]').its('length');

    // Type in search input
    cy.get('[data-testid="search-input"]').type('John');

    // Verify filtered results
    cy.get('[data-testid="table-row"]').each(($row) => {
      cy.wrap($row).should('contain.text', 'John');
    });

    // Verify row count decreased
    cy.get('[data-testid="table-row"]').its('length').should('be.lessThan', initialRowCount);
  });

  it('should display all rows when search input is cleared', () => {
    // Get initial row count
    cy.get('[data-testid="table-row"]').then(($rows) => {
      const initialCount = $rows.length;

      // Type search term
      cy.get('[data-testid="search-input"]').type('John');
      cy.get('[data-testid="table-row"]').should('have.length.lessThan', initialCount);

      // Clear search input
      cy.get('[data-testid="search-input"]').clear();

      // Verify all rows are displayed again
      cy.get('[data-testid="table-row"]').should('have.length', initialCount);
    });
  });

  it('should show no results message when search returns empty', () => {
    // Type non-existent search term
    cy.get('[data-testid="search-input"]').type('XYZ123NonExistent');

    // Verify no rows are displayed
    cy.get('[data-testid="table-row"]').should('have.length', 0);

    // Verify empty state message
    cy.get('[data-testid="empty-state-message"]').should('be.visible').and('contain.text', 'No results found');
  });

  it('should filter table with special characters in search', () => {
    // Type search term with special characters
    cy.get('[data-testid="search-input"]').type('test@example.com');

    // Verify filtered results contain the special characters
    cy.get('[data-testid="table-row"]').each(($row) => {
      cy.wrap($row).should('contain.text', 'test@example.com');
    });
  });

  it('should perform case-insensitive search', () => {
    // Type lowercase search term
    cy.get('[data-testid="search-input"]').type('john');

    // Get count of results
    cy.get('[data-testid="table-row"]').then(($rows) => {
      const lowercaseCount = $rows.length;

      // Clear and search with uppercase
      cy.get('[data-testid="search-input"]').clear().type('JOHN');

      // Verify same number of results
      cy.get('[data-testid="table-row"]').should('have.length', lowercaseCount);
    });
  });

  it('should filter across multiple columns', () => {
    // Type search term that exists in multiple columns
    cy.get('[data-testid="search-input"]').type('2024');

    // Verify results contain the search term in any visible column
    cy.get('[data-testid="table-row"]').each(($row) => {
      cy.wrap($row).invoke('text').should('include', '2024');
    });
  });

  it('should handle rapid typing and debounce correctly', () => {
    // Type rapidly
    cy.get('[data-testid="search-input"]').type('J', { delay: 50 });
    cy.get('[data-testid="search-input"]').type('o', { delay: 50 });
    cy.get('[data-testid="search-input"]').type('h', { delay: 50 });
    cy.get('[data-testid="search-input"]').type('n', { delay: 50 });

    // Wait for debounce and verify results
    cy.get('[data-testid="table-row"]').each(($row) => {
      cy.wrap($row).should('contain.text', 'John');
    });
  });

  it('should maintain filter when table data updates', () => {
    // Apply filter
    cy.get('[data-testid="search-input"]').type('John');
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Trigger data refresh
    cy.get('[data-testid="refresh-button"]').click();

    // Verify filter is still applied
    cy.get('[data-testid="search-input"]').should('have.value', 'John');
    cy.get('[data-testid="table-row"]').each(($row) => {
      cy.wrap($row).should('contain.text', 'John');
    });
  });
});
